        params: {
          include: "field_image,uid,uid.user_picture",
          sort: "-created",
          "filter[id][condition][path]": "id",
          "filter[id][condition][operator]": "<>",
          "filter[id][condition][value]": post.id,
        },
      },
    );
  }

  return {
    props: {
      preview: context.preview || false,
      post,
      morePosts,
    },
  };
}

