export const getServerSideProps = async (
  context?: GetServerSidePropsContext,
) => {
  const post = await e
    .select(e.Post, (post) => ({
      id: true,
      title: true,
      content: true,
      publishedISO: true,
      authorName: true,
      filter: e.op(post.id, "=", e.uuid(context!.params!.id as string)),
    }))
    .run(client);

  return { props: post! };
};

