          },
        );
        const movies = await moviesTxResultPromise;
        res.status(200).json({ success: true, movies });
      } catch (error) {
        res.status(400).json({ success: false });
      }
      break;
    default:
      res.status(400).json({ success: false });
      break;
  }
}

