          onClick={(e) => {
            e.preventDefault();
            toggleComplete();
          }}
        >
          {done ? "not done" : "done"}
        </button>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            deleteTodo();
          }}
          className=" p-1 bg-red-500 text-white rounded font-bold"
        >
          delete
        </button>
      </div>
    </li>
